{
  "name": "SMC40步进电机控制器",
  "name_en": "SMC40 Stepper Motor Controller",
  "manufacturer": "Anaheim Automation",
  "description": "这是一台用于驱动步进电机的运动控制器，可按设定方向和角度实现精密旋转定位，适合实验室中样品台、光学元件或机械部件的角度调整与重复转动。",
  "description_en": "This is a motion controller for driving a stepper motor. It provides precise angular positioning with configurable direction and angle, and is suitable in laboratories for rotating sample mounts, optical components, or other mechanical parts.",
  "tag_hints": [
    "stepper motor control",
    "rotary positioning",
    "angular motion",
    "precision rotation",
    "motorized stage control"
  ],
  "actions": [
    {
      "action_name": "auto-heading",
      "description": "获取/设置旋转方向（顺时针或逆时针）",
      "description_en": "Get/set the rotation direction (clockwise or counterclockwise)."
    },
    {
      "action_name": "auto-stepangle",
      "description": "获取/设置步进角",
      "description_en": "Get/set the step angle."
    },
    {
      "action_name": "auto-zero",
      "description": "将位置归零或回到零位",
      "description_en": "Zero the position or return to the zero position."
    },
    {
      "action_name": "auto-init",
      "description": "初始化设备",
      "description_en": "Initialize the device."
    },
    {
      "action_name": "auto-IDN",
      "description": "查询设备标识信息",
      "description_en": "Query the device identification information."
    },
    {
      "action_name": "auto-WAI",
      "description": "等待当前操作完成",
      "description_en": "Wait for the current operation to complete."
    },
    {
      "action_name": "auto-TRG",
      "description": "触发设备执行动作",
      "description_en": "Trigger the device to execute an action."
    },
    {
      "action_name": "auto-move",
      "description": "按指定方向旋转指定角度，可选择等待完成",
      "description_en": "Rotate by a specified angle in the selected direction, optionally waiting for completion."
    }
  ]
}

